package com.abyssredemption.abstool.client.serverstats;
import com.abyssredemption.abstool.client.serverstats.gui.ServerStatsScreen; import com.abyssredemption.abstool.client.serverstats.model.*; import com.abyssredemption.abstool.client.serverstats.network.*; import com.abyssredemption.abstool.client.serverstats.network.payload.*; import com.mojang.blaze3d.platform.InputConstants; import net.minecraft.client.KeyMapping; import net.minecraft.client.Minecraft; import net.minecraft.resources.Identifier; import net.neoforged.neoforge.client.event.*; import net.neoforged.neoforge.client.network.ClientPacketDistributor; import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent; import net.neoforged.neoforge.network.registration.PayloadRegistrar; import java.util.*;
public final class ServerStatsClient { private static final ServerStatsState STATE=new ServerStatsState(); private static final KeyMapping OPEN_KEY=new KeyMapping("key.abstool.serverstats",InputConstants.UNKNOWN.getValue(),KeyMapping.Category.register(Identifier.fromNamespaceAndPath("abstool","general"))); private static long nextId; private static int checks,ticks; private ServerStatsClient(){} public static ServerStatsState state(){return STATE;}
 public static void registerKey(RegisterKeyMappingsEvent e){e.register(OPEN_KEY);} public static void register(RegisterPayloadHandlersEvent e){PayloadRegistrar r=e.registrar("1").optional();r.playToServer(HelloRequestPayload.TYPE,HelloRequestPayload.CODEC,(p,c)->{});r.playToServer(LeaderboardRequestPayload.TYPE,LeaderboardRequestPayload.CODEC,(p,c)->{});r.playToClient(HelloResponsePayload.TYPE,HelloResponsePayload.CODEC,(p,c)->onHello(p));r.playToClient(LeaderboardResponsePayload.TYPE,LeaderboardResponsePayload.CODEC,(p,c)->onBoard(p));r.playToClient(StatsErrorPayload.TYPE,StatsErrorPayload.CODEC,(p,c)->STATE.availability(ServerStatsAvailability.ERROR));}
 public static void tick(ClientTickEvent.Post e){Minecraft mc=Minecraft.getInstance();if(OPEN_KEY.consumeClick())open();if(mc.getConnection()==null){if(STATE.availability()!=ServerStatsAvailability.UNKNOWN)STATE.clear();return;}if(STATE.availability()==ServerStatsAvailability.UNKNOWN&&ticks++%20==0&&checks<3){checks++;if(mc.getConnection().hasChannel(HelloRequestPayload.TYPE.id())){STATE.availability(ServerStatsAvailability.CHECKING);ClientPacketDistributor.sendToServer(new HelloRequestPayload(1));}else if(checks>=3)STATE.availability(ServerStatsAvailability.UNSUPPORTED);}}
 private static void onHello(HelloResponsePayload p){if(p.protocolVersion()!=1){STATE.availability(ServerStatsAvailability.PROTOCOL_MISMATCH);return;}STATE.hello(p.capabilities(),p.currentWeekKey());request(LeaderboardType.PLAYTIME,1,true);} private static void onBoard(LeaderboardResponsePayload p){if(p.protocolVersion()!=1||p.totalPages()<1||p.page()<1||p.entries().size()>100)return;var t=LeaderboardType.fromNetworkId(p.leaderboardType());if(t.isEmpty())return;List<ClientLeaderboardEntry> es=p.entries().stream().map(e->new ClientLeaderboardEntry(e.rank(),e.uuid(),e.playerName().isBlank()?"未知玩家":e.playerName(),Math.max(0,e.value()),e.online())).toList();STATE.put(new ClientLeaderboardPage(t.get(),p.page(),p.totalPages(),p.totalEntries(),p.generatedAtEpochMillis(),p.contextLabel(),es));}
 public static void request(LeaderboardType t,int page,boolean force){page=Math.max(1,page);if(STATE.availability()==ServerStatsAvailability.READY&&STATE.supports(t)&&(force||!STATE.fresh(t,page)))ClientPacketDistributor.sendToServer(new LeaderboardRequestPayload(1,++nextId,t.networkId(),page));} public static void open(){Minecraft mc=Minecraft.getInstance();if(mc.getConnection()!=null)mc.setScreenAndShow(new ServerStatsScreen(null));}
}
